  }
  .toc a:hover { background: rgba(43,125,233,0.3); color: white; }
  /* ---- LAYOUT ---- */
  .container { max-width: 1280px; margin: 0 auto; padding: 0 40px; }
  .section { padding: 56px 0; }
  .section + .section { border-top: 1px solid var(--gray-border); }
  .section-header { margin-bottom: 36px; }
  .section-tag {
    display: inline-block;
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--blue-accent);
    background: rgba(43,125,233,0.1);
    padding: 4px 10px;
    border-radius: 3px;
    margin-bottom: 10px;
  }
  h2 { font-size: 26px; font-weight: 800; color: var(--blue-dark); }
  h3 { font-size: 17px; font-weight: 700; color: var(--blue-dark); margin-bottom: 12px; }
  .lead {
    font-size: 15px;
    color: var(--text-secondary);
    max-width: 840px;
    margin-top: 8px;
    line-height: 1.7;
  }
  /* ---- CARDS ---- */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 36px;
  }
  .kpi-card {
    background: white;
    border-radius: 8px;
    padding: 20px;
    border: 1px solid var(--gray-border);
