  .insight-icon { font-size: 22px; margin-bottom: 8px; }
  .insight-title { font-size: 13px; font-weight: 700; color: var(--blue-dark); margin-bottom: 6px; }
  .insight-body { font-size: 13px; color: var(--text-secondary); line-height: 1.6; }
  /* ---- EXEC OVERVIEW ---- */
  .exec-overview {
    background: linear-gradient(135deg, var(--blue-dark) 0%, var(--blue-mid) 100%);
    border-radius: 12px;
    padding: 40px 48px;
    color: white;
