    font-size: 11px;
    font-weight: 800;
    letter-spacing: 2px;
    color: rgba(255,255,255,0.5);
    margin-bottom: 8px;
  }
  .exec-finding-title {
    font-size: 14px;
    font-weight: 700;
    margin-bottom: 8px;
    color: rgba(255,255,255,0.95);
  }
