    color: rgba(255,255,255,0.72);
    line-height: 1.6;
  }
  /* ---- RECOMMENDATIONS ---- */
  .rec-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
    gap: 20px;
