  .rec-title { font-size: 15px; font-weight: 700; color: var(--blue-dark); margin-bottom: 8px; }
  .rec-body { font-size: 13px; color: var(--text-secondary); line-height: 1.65; margin-bottom: 12px; }
  .rec-evidence {
    font-size: 12px;
    color: var(--blue-accent);
    background: rgba(43,125,233,0.08);
    border-left: 3px solid var(--blue-accent);
    padding: 8px 12px;
    border-radius: 0 4px 4px 0;
