function pluginHistBand(cutIdx) {
  return {
    id: 'histBand',
    beforeDraw(chart) {
      const {ctx, chartArea: {left, right, top, bottom}, scales: {x}} = chart;
      if (!x) return;
      const xCut = x.getPixelForValue(cutIdx + 0.5);
      ctx.save();
      ctx.fillStyle = 'rgba(43,125,233,0.05)';
      ctx.fillRect(xCut, top, right - xCut, bottom - top);
      ctx.setLineDash([5,4]);
      ctx.strokeStyle = 'rgba(43,125,233,0.35)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(xCut, top);
      ctx.lineTo(xCut, bottom);
      ctx.stroke();
      ctx.restore();
    }
  };
}

